syntax:
template< class T >
struct Derived : T {
    using T::T; // inherits all constructors from base class T
};

code_example:
#include <iostream>

struct Base {
    Base() { std::cout << "Default Base constructor\n"; }
    Base(int x) { std::cout << "Base constructor with int: " << x << '\n'; }
};

template< class T >
struct Derived : T {
    using T::T; // inherit constructors from T
};

int main() {
    Derived<Base> obj1; // calls Base()
    Derived<Base> obj2(42); // calls Base(int)
    return 0;
}
